      pilihan: [
        { id: "a", teks: "Menolak tawaran dan melanjutkan perjuangan bersenjata untuk kemerdekaan penuh.", konsekuensi: "Ini skenario alternatif. Tuntutan kemerdekaan tetap terjaga, tetapi konflik dan penderitaan warga akan berlanjut." },
        { id: "b", teks: "Menerima otonomi luas dan menyerahkan senjata di bawah pengawasan internasional.", konsekuensi: "Pilihan ini paling dekat dengan yang terjadi. Konflik berakhir, dan sebagian tuntutan dipenuhi melalui otonomi khusus.", historis: true },
        { id: "c", teks: "Meminta perundingan ditunda sampai pemerintah menyetujui referendum.", konsekuensi: "Ini skenario alternatif. Tuntutan lebih tegas, tetapi kesempatan damai yang muncul setelah tsunami bisa hilang." },
      ],
      hasilHistoris: "Gerakan Aceh Merdeka menerima otonomi luas dan menyerahkan senjata. Pemilihan kepala daerah pada Desember 2006 menjadi ujian pertama pelaksanaan perjanjian.",
